import { Button } from "@/components/ui/button"
import { Mascot } from "@/components/ui/mascot"

const links = ["Product", "Pricing", "Notes", "Sign in"]

function AnnouncementBarHeader() {
  return (
    <header className="flex items-center justify-between gap-4 px-6 py-5 [--ll-blend:normal]">
      <a href="#top" className="flex items-center gap-2 font-script text-3xl leading-none font-bold text-ink">
        <Mascot pose="idle" size={32} />
        penmark
      </a>
      <nav aria-label="Main" className="hidden items-center gap-6 text-base text-ink @lg:flex">
        {links.map((l) => (
          <a key={l} href={`#${l.toLowerCase().replace(/\s+/g, "-")}`} className="underline-offset-4 hover:underline">
            {l}
          </a>
        ))}
      </nav>
      <Button size="sm">Start free</Button>
    </header>
  )
}

export { AnnouncementBarHeader }

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { AnnouncementBarHeader } from "@/components/blocks/announcement-bar/components/announcement-bar-header"
import { AnnouncementBarStrip } from "@/components/blocks/announcement-bar/components/announcement-bar-strip"

export default function AnnouncementBarBlock() {
  const [open, setOpen] = React.useState(true)
  const strip = React.useRef<HTMLElement>(null)
  const bringBack = React.useRef<HTMLButtonElement>(null)
  const handOver = React.useRef(false)
  React.useEffect(() => {
    if (!handOver.current) return
    handOver.current = false
    if (open) strip.current?.focus()
    else bringBack.current?.focus()
  }, [open])
  const toggle = (next: boolean) => {
    handOver.current = true
    setOpen(next)
  }

  return (
    <div className="@container w-full">
      {open ? (
        <AnnouncementBarStrip
          ref={strip}
          tabIndex={-1}
          message="Penmark 2.0 is here: tape you can peel, and pages that turn."
          linkLabel="Read the notes"
          href="#notes"
          onDismiss={() => toggle(false)}
          className="outline-none"
        />
      ) : (
        <div className="flex justify-center px-3 pt-3">
          <Button ref={bringBack} type="button" variant="link" size="sm" onClick={() => toggle(true)}>
            Bring the announcement back
          </Button>
        </div>
      )}
      <AnnouncementBarHeader />
    </div>
  )
}
